head.script:
scwin.trigger1_onclick = function(e) {
    dataList1.insertJSON(0, jsonData2);
};
scwin.checkTable = function() {
    return WebSquare.wUnit.getJq('#wq_uuid_3_body_tbody').children().length > 0;
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkTable()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.jsonData1 = [];
    window.jsonData2 = [];
    for (var i = 0; i < 400; i++) {
        window.tmp = {
            col1: i + "",
            col2: i + 'sample'
        }
        jsonData1.push(tmp);
    };
    for (var i = 0; i < 400; i++) {
        window.tmp = {
            col1: i + "",
            col2: i + 'sample2'
        }
        jsonData2.push(tmp);
    };
    /*
        scwin.init = function(){
        	dataList1.setJSON(jsonData1);
        };
        */
    //scwin.init();
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
